1	package retention
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7	)
8	
9	// RegisterInput 是登记一份档案所需的信息。
10	//
11	// 编号和类别不能是空白；日期必须是 ParseDate 能解析的真实日期；
12	// 截止日可以与起算日相同，但不能更早。
13	type RegisterInput struct {
14		ID       string
15		Category string
16		Start    Date
17		End      Date
18	}
19	
20	// FreezeInput 是为档案新增一条冻结所需的信息。
21	type FreezeInput struct {
22		ArchiveID string
23		FreezeID  string
24		Reason    string
25		FrozenOn  Date
26	}
27	
28	// ReleaseInput 是解除一条冻结所需的信息。
29	type ReleaseInput struct {
30		ArchiveID  string
31		FreezeID   string
32		Reason     string
33		ReleasedOn Date
34	}
35	
36	// DestructionRequest 是一次销毁申请。
37	//
38	// 一次申请可以选择多个档案。申请编号在所有成功申请中唯一，
39	// 处理日期即判断档案是否到期所依据的日期。
40	type DestructionRequest struct {
41		ApplicationID string
42		ProcessedOn   Date
43		ArchiveIDs    []string
44	}
45	
46	// normalizeText 去除首尾空白；空白字段统一按空白处理，避免同值异写。
47	func normalizeText(s string) string { return strings.TrimSpace(s) }
48	
49	func requireText(value, name string) (string, error) {
50		v := normalizeText(value)
51		if v == "" {
52			return "", fmt.Errorf("retention: %s不能为空白: %w", name, ErrBlankField)
53		}
54		return v, nil
55	}
56	
57	func requireDate(d Date, name string) error {
58		if d.IsZero() {
59			return fmt.Errorf("retention: %s缺失或无效，应为 YYYY-MM-DD: %w", name, ErrInvalidDate)
60		}
61		return nil
62	}
63	
64	// Register 登记一份档案。
65	//
66	// 编号重复或任一输入无效时明确失败，并且不写盘，已有记录不受影响。
67	func (s *Store) Register(in RegisterInput) error {
68		id, err := requireText(in.ID, "档案编号")
69		if err != nil {
70			return err
71		}
72		category, err := requireText(in.Category, "类别")
73		if err != nil {
74			return err
75		}
76		if err := requireDate(in.Start, "起算日"); err != nil {
77			return err
78		}
79		if err := requireDate(in.End, "保管截止日"); err != nil {
80			return err
81		}
82		if in.End.Before(in.Start) {
83			return fmt.Errorf("retention: 档案 %s 的保管截止日 %s 早于起算日 %s: %w",
84				id, in.End, in.Start, ErrRetentionEndBeforeStart)
85		}
86		return s.mutate(func(data *storeData) error {
87			if _, exists := data.Archives[id]; exists {
88				return fmt.Errorf("retention: 档案编号 %s 已登记: %w", id, ErrDuplicateID)
89			}
90			data.Archives[id] = &archiveRecord{
91				ID:       id,
92				Category: category,
93				Start:    in.Start,
94				End:      in.End,
95				Freezes:  nil,
96			}
97			return nil
98		})
99	}
100	
101	// Freeze 为档案登记一条冻结。
102	//
103	// 冻结编号在同一档案内唯一。档案不存在、已销毁、冻结编号重复或输入无效时失败。
104	func (s *Store) Freeze(in FreezeInput) error {
105		archiveID, err := requireText(in.ArchiveID, "档案编号")
106		if err != nil {
107			return err
108		}
109		freezeID, err := requireText(in.FreezeID, "冻结编号")
110		if err != nil {
111			return err
112		}
113		reason, err := requireText(in.Reason, "冻结原因")
114		if err != nil {
115			return err
116		}
117		if err := requireDate(in.FrozenOn, "冻结日期"); err != nil {
118			return err
119		}
120		return s.mutate(func(data *storeData) error {
121			ar, ok := data.Archives[archiveID]
122			if !ok {
123				return fmt.Errorf("retention: 档案 %s 不存在，不能新增冻结: %w", archiveID, ErrNotFound)
124			}
125			if ar.Destroyed {
126				return fmt.Errorf("retention: 档案 %s 已销毁，不能新增冻结: %w", archiveID, ErrDestroyed)
127			}
128			for _, f := range ar.Freezes {
129				if f.ID == freezeID {
130					return fmt.Errorf("retention: 档案 %s 内冻结编号 %s 已存在: %w",
131						archiveID, freezeID, ErrDuplicateFreezeID)
132				}
133			}
134			ar.Freezes = append(ar.Freezes, &freezeRecord{
135				ID:       freezeID,
136				Reason:   reason,
137				FrozenOn: in.FrozenOn,
138			})
139			return nil
140		})
141	}
142	
143	// Release 解除一条冻结。
144	//
145	// 必须填写解除日期与原因，解除日期不能早于该冻结的冻结日期。
146	// 解除只在原记录上标记，不删除冻结记录，也不影响同一档案的其他冻结。
147	// 不能解除不存在或已经解除的冻结。
148	func (s *Store) Release(in ReleaseInput) error {
149		archiveID, err := requireText(in.ArchiveID, "档案编号")
150		if err != nil {
151			return err
152		}
153		freezeID, err := requireText(in.FreezeID, "冻结编号")
154		if err != nil {
155			return err
156		}
157		reason, err := requireText(in.Reason, "解除原因")
158		if err != nil {
159			return err
160		}
161		if err := requireDate(in.ReleasedOn, "解除日期"); err != nil {
162			return err
163		}
164		return s.mutate(func(data *storeData) error {
165			ar, ok := data.Archives[archiveID]
166			if !ok {
167				return fmt.Errorf("retention: 档案 %s 不存在: %w", archiveID, ErrNotFound)
168			}
169			var fr *freezeRecord
170			for _, f := range ar.Freezes {
171				if f.ID == freezeID {
172					fr = f
173					break
174				}
175			}
176			if fr == nil {
177				return fmt.Errorf("retention: 档案 %s 下冻结 %s 不存在: %w",
178					archiveID, freezeID, ErrFreezeNotFound)
179			}
180			if fr.Released {
181				return fmt.Errorf("retention: 档案 %s 的冻结 %s 已经解除，不能重复解除: %w",
182					archiveID, freezeID, ErrFreezeAlreadyReleased)
183			}
184			if in.ReleasedOn.Before(fr.FrozenOn) {
185				return fmt.Errorf("retention: 解除日期 %s 早于冻结 %s 的冻结日期 %s: %w",
186					in.ReleasedOn, freezeID, fr.FrozenOn, ErrReleaseBeforeFreeze)
187			}
188			fr.Released = true
189			fr.ReleaseReason = reason
190			releasedOn := in.ReleasedOn
191			fr.ReleasedOn = &releasedOn
192			return nil
193		})
194	}
195	
196	// Destroy 办理一次销毁申请。
197	//
198	// 只有名单中全部档案都存在、按处理日期已到期（处理日期不早于截止日，
199	// 截止日当天即到期）、未销毁且没有未解除冻结时，才会同时完成销毁，
200	// 并生成一份内容此后不可更改的已关闭清册。
201	//
202	// 名单为空、名单内编号重复或任一档案不符合条件时，整次申请失败，
203	// 不会留下部分销毁或清册。
204	//
205	// 同一申请编号此前已经成功办理时：处理日期与档案集合完全相同（顺序无关）
206	// 则返回原清册；沿用编号但改变日期或档案集合则失败。失败过的申请
207	// 在条件改变后可以用同一编号再次提交。
208	func (s *Store) Destroy(req DestructionRequest) (Manifest, error) {
209		applicationID, err := requireText(req.ApplicationID, "申请编号")
210		if err != nil {
211			return Manifest{}, err
212		}
213		if err := requireDate(req.ProcessedOn, "处理日期"); err != nil {
214			return Manifest{}, err
215		}
216		if len(req.ArchiveIDs) == 0 {
217			return Manifest{}, fmt.Errorf("retention: 申请 %s 的销毁名单为空: %w",
218				applicationID, ErrEmptyDestructionList)
219		}
220	
221		// 规范化名单并检查名单内重复（输入校验先于任何业务判断）。
222		ids := make([]string, 0, len(req.ArchiveIDs))
223		for _, raw := range req.ArchiveIDs {
224			id, err := requireText(raw, "档案编号")
225			if err != nil {
226				return Manifest{}, err
227			}
228			ids = append(ids, id)
229		}
230		seen := make(map[string]struct{}, len(ids))
231		for _, id := range ids {
232			if _, dup := seen[id]; dup {
233				return Manifest{}, fmt.Errorf("retention: 申请 %s 的销毁名单中档案 %s 重复: %w",
234					applicationID, id, ErrDuplicateSelection)
235			}
236			seen[id] = struct{}{}
237		}
238	
239		var result Manifest
240		err = s.mutate(func(data *storeData) error {
241			// 已成功的申请编号：幂等返回原清册，或因内容不一致失败。
242			if existing, ok := data.Manifests[applicationID]; ok {
243				if !sameApplication(existing, req.ProcessedOn, seen) {
244					return fmt.Errorf("retention: 申请编号 %s 已成功使用，本次日期或档案集合与原申请不一致: %w",
245						applicationID, ErrApplicationMismatch)
246				}
247				result = manifestFromRecord(existing)
248				return nil
249			}
250	
251			// 逐份校验，任一不符合条件则整体放弃（此时尚未改动任何记录）。
252			for _, id := range ids {
253				ar, ok := data.Archives[id]
254				if !ok {
255					return fmt.Errorf("retention: 档案 %s 不存在: %w", id, ErrNotFound)
256				}
257				if ar.Destroyed {
258					return fmt.Errorf("retention: 档案 %s 已在清册 %s 中，不能再次销毁: %w",
259						id, ar.ManifestID, ErrArchiveAlreadyOnManifest)
260				}
261				if req.ProcessedOn.Before(ar.End) {
262					return fmt.Errorf("retention: 档案 %s 尚未到期（截止日 %s，处理日期 %s）: %w",
263						id, ar.End, req.ProcessedOn, ErrNotExpired)
264				}
265				for _, f := range ar.Freezes {
266					if !f.Released {
267						return fmt.Errorf("retention: 档案 %s 有未解除的冻结 %s: %w",
268							id, f.ID, ErrActiveFreeze)
269					}
270				}
271			}
272	
273			// 全部满足：生成关闭清册，内容为各档案当时登记内容的快照。
274			rec := &manifestRecord{
275				ApplicationID: applicationID,
276				ProcessedOn:   req.ProcessedOn,
277			}
278			ordered := append([]string(nil), ids...)
279			sort.Strings(ordered)
280			for _, id := range ordered {
281				ar := data.Archives[id]
282				rec.Entries = append(rec.Entries, manifestEntry{
283					ID:       ar.ID,
284					Category: ar.Category,
285					Start:    ar.Start,
286					End:      ar.End,
287				})
288				ar.Destroyed = true
289				ar.ManifestID = applicationID
290			}
291			data.Manifests[applicationID] = rec
292			result = manifestFromRecord(rec)
293			return nil
294		})
295		if err != nil {
296			return Manifest{}, err
297		}
298		return result, nil
299	}
300	
301	// sameApplication 判断已成功申请与本次提交的处理日期和档案集合是否完全一致（顺序无关）。
302	func sameApplication(existing *manifestRecord, processedOn Date, idSet map[string]struct{}) bool {
303		if !existing.ProcessedOn.Equal(processedOn) {
304			return false
305		}
306		if len(existing.Entries) != len(idSet) {
307			return false
308		}
309		for _, e := range existing.Entries {
310			if _, ok := idSet[e.ID]; !ok {
311				return false
312			}
313		}
314		return true
315	}
316	
317	func manifestFromRecord(rec *manifestRecord) Manifest {
318		m := Manifest{
319			ApplicationID: rec.ApplicationID,
320			ProcessedOn:   rec.ProcessedOn,
321			Entries:       make([]ManifestEntry, 0, len(rec.Entries)),
322		}
323		for _, e := range rec.Entries {
324			m.Entries = append(m.Entries, ManifestEntry{
325				ID:       e.ID,
326				Category: e.Category,
327				Start:    e.Start,
328				End:      e.End,
329			})
330		}
331		return m
332	}
333	
334	func freezeFromRecord(fr *freezeRecord) FreezeRecord {
335		out := FreezeRecord{
336			ID:            fr.ID,
337			Reason:        fr.Reason,
338			FrozenOn:      fr.FrozenOn,
339			Released:      fr.Released,
340			ReleaseReason: fr.ReleaseReason,
341		}
342		if fr.ReleasedOn != nil {
343			out.ReleasedOn = *fr.ReleasedOn
344		}
345		return out
346	}
347	
348	// History 按档案编号核对完整历史。
349	//
350	// 结果包含登记内容、全部冻结及解除历史、当前未解除冻结、销毁状态以及
351	// 对应的已关闭清册。档案未登记时 found 为 false（err 为 nil），
352	// 这是明确的不存在结果。
353	func (s *Store) History(archiveID string) (h ArchiveHistory, found bool, err error) {
354		id := normalizeText(archiveID)
355		if id == "" {
356			return ArchiveHistory{}, false, fmt.Errorf("retention: 档案编号不能为空白: %w", ErrBlankField)
357		}
358		err = s.view(func(data *storeData) error {
359			ar, ok := data.Archives[id]
360			if !ok {
361				return nil
362			}
363			found = true
364			h = ArchiveHistory{
365				ID:                    ar.ID,
366				Category:              ar.Category,
367				Start:                 ar.Start,
368				RetentionEnd:          ar.End,
369				Destroyed:             ar.Destroyed,
370				ManifestApplicationID: ar.ManifestID,
371				Freezes:               make([]FreezeRecord, 0, len(ar.Freezes)),
372			}
373			for _, fr := range ar.Freezes {
374				view := freezeFromRecord(fr)
375				h.Freezes = append(h.Freezes, view)
376				if !fr.Released {
377					h.ActiveFreezes = append(h.ActiveFreezes, view)
378				}
379			}
380			if ar.Destroyed && ar.ManifestID != "" {
381				if rec, ok := data.Manifests[ar.ManifestID]; ok {
382					m := manifestFromRecord(rec)
383					h.Manifest = &m
384				}
385			}
386			return nil
387		})
388		if err != nil {
389			return ArchiveHistory{}, false, err
390		}
391		return h, found, nil
392	}
393	
394	// Manifest 按申请编号查询一份已关闭清册。不存在时 found 为 false。
395	func (s *Store) GetManifest(applicationID string) (m Manifest, found bool, err error) {
396		id := normalizeText(applicationID)
397		if id == "" {
398			return Manifest{}, false, fmt.Errorf("retention: 申请编号不能为空白: %w", ErrBlankField)
399		}
400		err = s.view(func(data *storeData) error {
401			if rec, ok := data.Manifests[id]; ok {
402				m = manifestFromRecord(rec)
403				found = true
404			}
405			return nil
406		})
407		if err != nil {
408			return Manifest{}, false, err
409		}
410		return m, found, nil
411	}
