207		}
208	
209		// 空名单。
210		if _, err := s.Destroy(DestructionRequest{ApplicationID: "APP", ProcessedOn: MustParseDate("2025-01-10")}); !errors.Is(err, ErrEmptyDestructionList) {
211			t.Fatalf("空名单应失败，得到 %v", err)
212		}
213		// 名单内重复。
214		if _, err := s.Destroy(DestructionRequest{ApplicationID: "APP", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1", "A-1"}}); !errors.Is(err, ErrDuplicateSelection) {
215			t.Fatalf("重复名单应失败，得到 %v", err)
