219			t.Fatalf("含不存在档案应失败，得到 %v", err)
220		}
221		// A-3 有冻结：整次失败，A-1、A-2 必须仍未销毁，且没有清册。
222		if _, err := s.Destroy(DestructionRequest{ApplicationID: "APP", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1", "A-2", "A-3"}}); !errors.Is(err, ErrActiveFreeze) {
223			t.Fatalf("含冻结档案应整次失败，得到 %v", err)
224		}
225		for _, id := range []string{"A-1", "A-2", "A-3"} {
226			h, found, _ := s.History(id)
227			if !found || h.Destroyed {
228				t.Fatalf("失败后 %s 不应被销毁: %+v", id, h)
229			}
230		}
231		if _, found, err := s.GetManifest("APP"); err != nil || found {
232			t.Fatalf("失败的申请不应留下清册，found=%v err=%v", found, err)
233		}
234	
235		// 条件改变（解除 A-3）后，同一申请编号可再次提交并成功。
236		if err := s.Release(ReleaseInput{ArchiveID: "A-3", FreezeID: "F", Reason: "解决", ReleasedOn: MustParseDate("2025-01-11")}); err != nil {
237			t.Fatal(err)
238		}
239		m, err := s.Destroy(DestructionRequest{ApplicationID: "APP", ProcessedOn: MustParseDate("2025-01-12"), ArchiveIDs: []string{"A-1", "A-2", "A-3"}})
240		if err != nil {
241			t.Fatalf("条件满足后同编号应可成功，得到 %v", err)
242		}
243		if len(m.Entries) != 3 {
244			t.Fatalf("清册应有 3 条，得到 %d", len(m.Entries))
245		}
246		// 清册为快照：条目按编号排序，登记字段取自关闭当时。
247		if m.Entries[0].ID != "A-1" || m.Entries[1].ID != "A-2" || m.Entries[2].ID != "A-3" {
248			t.Fatalf("清册条目排序不稳定: %+v", m.Entries)
249		}
250		if m.Entries[2].Category != "图纸" || !m.Entries[2].Start.Equal(MustParseDate("2020-01-01")) {
251			t.Fatalf("清册快照字段不正确: %+v", m.Entries[2])
252		}
253	}
